import React, { Suspense, useState, useEffect } from 'react';
import styled from '@emotion/styled';
import { theme, AppSwitcher, putSetting, getSetting, setStorageProvider } from '@atlantis/shared';
// styled and theme are used by LoadingScreen / ErrorScreen below
import type { AppDefinition } from '@atlantis/shared';
import type { User } from '@supabase/supabase-js';
import { HomeScreen } from './HomeScreen';
import { AuthGate } from './AuthGate';
import { UserMenu } from './UserMenu';
import { supabase, signOut } from './supabase';
import { supabaseProvider } from './supabaseProvider';
import APP_CONFIG from './apps.config';

const MarkdownApp = React.lazy(() => import('markdown/App'));
const EarthApp = React.lazy(() => import('earth/App'));
const TechScopeApp = React.lazy(() => import('techscope/App'));
const CityPulseApp = React.lazy(() => import('citypulse/App'));
const DevHubApp = React.lazy(() => import('devhub/App'));
const CosmosApp = React.lazy(() => import('cosmos/App'));
const StockPulseApp = React.lazy(() => import('stockpulse/App'));
const MdPadApp = React.lazy(() => import('mdpad/App'));
const RegexLabApp = React.lazy(() => import('regexlab/App'));
const JsonExplorerApp = React.lazy(() => import('jsonexplorer/App'));
const CodeDiffApp = React.lazy(() => import('codediff/App'));
const JsFiddleApp = React.lazy(() => import('playground/App'));
const JwtInspectorApp = React.lazy(() => import('jwtinspector/App'));
const ColorLabApp = React.lazy(() => import('colorlab/App'));
const CronBuilderApp = React.lazy(() => import('cronbuilder/App'));
const CsvExplorerApp = React.lazy(() => import('csvexplorer/App'));
const ChartBuilderApp = React.lazy(() => import('chartbuilder/App'));
const MermaidPadApp = React.lazy(() => import('mermaidpad/App'));
const MathBlogApp = React.lazy(() => import('mathblog/App'));
const LeitorApp = React.lazy(() => import('leitor/App'));
const PortuguesApp = React.lazy(() => import('portugues/App'));
const EstudoDoMeioApp = React.lazy(() => import('estudodomeio/App'));
const WeatherApp = React.lazy(() => import('weather/App'));
const ApiExplorerApp = React.lazy(() => import('apiexplorer/App'));

const APPS: AppDefinition[] = APP_CONFIG
  .filter((app) => app.enabled)
  .map(({ id, label, hash }) => ({ id, label, hash }));

const FadeWrapper = styled.div`
  @keyframes fadeIn {
    from { opacity: 0; }
    to   { opacity: 1; }
  }
  animation: fadeIn 0.2s ease-in-out;
  height: 100%;
`;

const LoadingScreen = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100vh;
  background: ${theme.colors.mainBg};
  color: ${theme.colors.mainTextMuted};
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeBase};
`;

const ErrorScreen = styled(LoadingScreen)`
  flex-direction: column;
  gap: ${theme.spacing.md};
`;

const ErrorTitle = styled.h2`
  color: ${theme.colors.mainText};
  font-size: ${theme.typography.fontSizeLg};
`;


interface RemoteErrorBoundaryState {
  hasError: boolean;
}

class RemoteErrorBoundary extends React.Component<
  { name: string; children: React.ReactNode },
  RemoteErrorBoundaryState
> {
  constructor(props: { name: string; children: React.ReactNode }) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(): RemoteErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error) {
    console.error(`[RemoteErrorBoundary] "${this.props.name}" threw:`, error);
  }

  render() {
    if (this.state.hasError) {
      return (
        <ErrorScreen>
          <ErrorTitle>Failed to load &ldquo;{this.props.name}&rdquo;</ErrorTitle>
          <p>Make sure the remote app is running on the correct port.</p>
        </ErrorScreen>
      );
    }
    return this.props.children;
  }
}

function getAppFromHash(hash: string): string {
  const path = hash.replace(/^#\/?/, '');
  if (!path || path === 'home') return 'home';
  if (path.startsWith('earth')) return 'earth';
  if (path.startsWith('techscope')) return 'techscope';
  if (path.startsWith('citypulse')) return 'citypulse';
  if (path.startsWith('devhub')) return 'devhub';
  if (path.startsWith('cosmos')) return 'cosmos';
  if (path.startsWith('stockpulse')) return 'stockpulse';
  if (path.startsWith('mdpad')) return 'mdpad';
  if (path.startsWith('regexlab')) return 'regexlab';
  if (path.startsWith('jsonexplorer')) return 'jsonexplorer';
  if (path.startsWith('codediff')) return 'codediff';
  if (path.startsWith('playground')) return 'playground';
  if (path.startsWith('blog')) return 'markdown';
  if (path.startsWith('jwtinspector')) return 'jwtinspector';
  if (path.startsWith('colorlab')) return 'colorlab';
  if (path.startsWith('cronbuilder')) return 'cronbuilder';
  if (path.startsWith('csvexplorer')) return 'csvexplorer';
  if (path.startsWith('chartbuilder')) return 'chartbuilder';
  if (path.startsWith('mermaidpad')) return 'mermaidpad';
  if (path.startsWith('math')) return 'mathblog';
  if (path.startsWith('portugues')) return 'portugues';
  if (path.startsWith('estudodomeio')) return 'estudodomeio';
  if (path.startsWith('weather')) return 'weather';
  if (path.startsWith('leitor')) return 'leitor';
  if (path.startsWith('apiexplorer')) return 'apiexplorer';
  return 'home';
}

const RECENT_APPS_KEY = 'shell:recent';
const PINNED_APPS_KEY = 'shell:pinned';
const RECENT_MAX = 8;

function parseIds(raw: string | null): string[] {
  try { return JSON.parse(raw ?? '[]'); } catch { return []; }
}


const NEEDS_AUTH = new Set(
  APP_CONFIG.filter((a) => a.needsAuth).map((a) => a.id)
);

export default function App() {
  const [activeAppId, setActiveAppId] = useState(() => getAppFromHash(window.location.hash));
  const [recentApps,  setRecentApps]  = useState<string[]>([]);
  const [pinnedApps,  setPinnedApps]  = useState<string[]>([]);
  const [user,        setUser]        = useState<User | null>(null);
  const [authReady,   setAuthReady]   = useState(false);

  // Subscribe to Supabase auth state and switch storage provider accordingly
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      const u = data.session?.user ?? null;
      setUser(u);
      setStorageProvider(u ? supabaseProvider : null);
      setAuthReady(true);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      const u = session?.user ?? null;
      setUser(u);
      setStorageProvider(u ? supabaseProvider : null);
    });
    return () => subscription.unsubscribe();
  }, []);

  // Load persisted state from IDB on mount
  useEffect(() => {
    getSetting(RECENT_APPS_KEY).then((v) => setRecentApps(parseIds(v)));
    getSetting(PINNED_APPS_KEY).then((v) => setPinnedApps(parseIds(v)));
  }, []);

  useEffect(() => {
    const onHashChange = () => setActiveAppId(getAppFromHash(window.location.hash));
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  // Track recently used whenever activeAppId changes (skip 'home')
  useEffect(() => {
    if (!activeAppId || activeAppId === 'home') return;
    setRecentApps((prev) => {
      const next = [activeAppId, ...prev.filter((id) => id !== activeAppId)].slice(0, RECENT_MAX);
      putSetting(RECENT_APPS_KEY, JSON.stringify(next));
      return next;
    });
  }, [activeAppId]);

  const handleTogglePin = (appId: string) => {
    setPinnedApps((prev) => {
      const next = prev.includes(appId) ? prev.filter((id) => id !== appId) : [...prev, appId];
      putSetting(PINNED_APPS_KEY, JSON.stringify(next));
      return next;
    });
  };

  const appLabel = APP_CONFIG.find((a) => a.id === activeAppId)?.label ?? activeAppId;

  // Block access to protected apps until auth is ready, then gate if unauthenticated
  if (!authReady) return <LoadingScreen>Loading…</LoadingScreen>;

  if (NEEDS_AUTH.has(activeAppId) && !user) {
    return (
      <AuthGate
        appLabel={appLabel}
        onBack={() => { window.location.hash = '#/home'; }}
      />
    );
  }

  const topBarRight = (
    <>
      {user && (
        <UserMenu
          user={{ name: user.user_metadata?.full_name, email: user.email ?? '', avatarUrl: user.user_metadata?.avatar_url }}
          onSignOut={signOut}
        />
      )}
      <AppSwitcher apps={APPS} activeAppId={activeAppId} />
    </>
  );

  if (activeAppId === 'home') {
    return (
      <FadeWrapper key="home">
        <HomeScreen
          apps={APPS}
          recentAppIds={recentApps}
          pinnedAppIds={pinnedApps}
          onTogglePin={handleTogglePin}
          onSelect={(app) => { window.location.hash = app.hash; }}
          user={user ? { name: user.user_metadata?.full_name, email: user.email ?? '', avatarUrl: user.user_metadata?.avatar_url } : null}
          onSignOut={signOut}
        />
      </FadeWrapper>
    );
  }

  return (
    <RemoteErrorBoundary name={activeAppId}>
      <Suspense fallback={<LoadingScreen>Loading…</LoadingScreen>}>
        <FadeWrapper key={activeAppId}>
        {activeAppId === 'earth' && <EarthApp topBarRight={topBarRight} />}
        {activeAppId === 'markdown' && <MarkdownApp topBarRight={topBarRight} />}
        {activeAppId === 'techscope' && <TechScopeApp topBarRight={topBarRight} />}
        {activeAppId === 'citypulse' && <CityPulseApp topBarRight={topBarRight} />}
        {activeAppId === 'devhub' && <DevHubApp topBarRight={topBarRight} />}
        {activeAppId === 'cosmos' && <CosmosApp topBarRight={topBarRight} />}
        {activeAppId === 'stockpulse' && <StockPulseApp topBarRight={topBarRight} />}
        {activeAppId === 'mdpad' && <MdPadApp topBarRight={topBarRight} />}
        {activeAppId === 'regexlab' && <RegexLabApp topBarRight={topBarRight} />}
        {activeAppId === 'jsonexplorer' && <JsonExplorerApp topBarRight={topBarRight} />}
        {activeAppId === 'codediff' && <CodeDiffApp topBarRight={topBarRight} />}
        {activeAppId === 'playground' && <JsFiddleApp topBarRight={topBarRight} />}
        {activeAppId === 'jwtinspector' && <JwtInspectorApp topBarRight={topBarRight} />}
        {activeAppId === 'colorlab' && <ColorLabApp topBarRight={topBarRight} />}
        {activeAppId === 'cronbuilder' && <CronBuilderApp topBarRight={topBarRight} />}
        {activeAppId === 'csvexplorer' && <CsvExplorerApp topBarRight={topBarRight} />}
        {activeAppId === 'chartbuilder' && <ChartBuilderApp topBarRight={topBarRight} />}
        {activeAppId === 'mermaidpad' && <MermaidPadApp topBarRight={topBarRight} />}
        {activeAppId === 'mathblog' && <MathBlogApp topBarRight={topBarRight} />}
        {activeAppId === 'portugues' && <PortuguesApp topBarRight={topBarRight} />}
        {activeAppId === 'estudodomeio' && <EstudoDoMeioApp topBarRight={topBarRight} />}
        {activeAppId === 'weather' && <WeatherApp topBarRight={topBarRight} />}
        {activeAppId === 'leitor' && <LeitorApp topBarRight={topBarRight} />}
        {activeAppId === 'apiexplorer' && <ApiExplorerApp topBarRight={topBarRight} />}
        </FadeWrapper>
      </Suspense>
    </RemoteErrorBoundary>
  );
}
