/**
 * Central configuration for all apps.
 * Edit apps.config.json to add/remove apps or change their properties.
 * Set `enabled: false` to hide an app from the home screen and navigation.
 */
import appsData from './apps.config.json';

export interface AppConfig {
  id: string;
  port: number;
  label: string;
  hash: string;
  icon: string;
  description: string;
  color: string;
  enabled: boolean;
  category: string;
  needsAuth: boolean;
}

const APPS: AppConfig[] = appsData;

export default APPS;
